"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[506],{6506:(e,i,a)=>{a.d(i,{$:()=>s,Vz:()=>n,fu:()=>l,sQ:()=>r,zO:()=>t});let l={eyebrow:"HAKKIMIZDA",introParagraphs:["AYBARİst AKADEMİ, 33 yıllık k\xf6kl\xfc eğitim deneyimini, alanında uzman ve profesyonel, yeni nesil Maarif Modeline h\xe2kim \xf6ğretmen kadrosuyla birleştiren \xe7ağdaş bir eğitim kurumudur.","Eğitimde \xe7eyrek asrı aşan bu g\xfc\xe7l\xfc tecr\xfcbemizle, her \xf6ğrencimizi hayallerindeki geleceğe sevgi, ilgi ve akademik disiplinle hazırlıyoruz. Bizim i\xe7in başarı bir tesad\xfcf değil; doğru y\xf6nlendirme, kesintisiz takip ve doğru y\xf6ntemlerle kazanılan kalıcı bir alışkanlıktır."],solutionsIntro:"\xd6ğrencilerimizin potansiyelini zirveye taşımak ve eğitim yolculuğunda fark yaratmak adına sunduğumuz \xe7\xf6z\xfcmler:",solutions:[{index:"01",title:"Kişiye \xd6zg\xfc Bireyselleştirilmiş Program",description:"Her \xf6ğrencinin \xf6ğrenme hızı, algı d\xfcnyası ve ihtiya\xe7ları farklıdır. AYBARİst AKADEMİ'de eğitim, standart kalıplarla değil, \xf6ğrencinin eksiklerine ve hedeflerine \xf6zel hazırlanan bireysel programlarla y\xfcr\xfct\xfcl\xfcr."},{index:"02",title:"S\xfcrekli Performans Takibi ve Sınav Analizleri",description:"Gelişimi şansa bırakmıyoruz. D\xfczenli olarak ger\xe7ekleştirdiğimiz performans takipleri ve detaylı sınav analizleri sayesinde, \xf6ğrencinin zorlandığı noktaları (problemleri) anında saptıyor, nokta atışı m\xfcdahalelerle sorunu hızla gideriyoruz."},{index:"03",title:"Alanında Uzman ve Profesyonel Kadro",description:"Derslerimizi, sadece branşına h\xe2kim değil, aynı zamanda \xf6ğrenciyle doğru iletişim kurabilen, motivasyonu y\xfcksek ve tecr\xfcbeli uzman \xf6ğretmenlerimizle y\xfcr\xfct\xfcyoruz."}],reachHeadline:"Eğitimde Sınır Tanımıyoruz",reachItems:[{title:"İstanbul’un T\xfcm İl\xe7elerinde",description:"Evinizin konforunda, g\xfcvenli ve verimli bir ortamda birebir y\xfcz y\xfcze \xf6zel ders hizmeti sağlıyoruz."},{title:"T\xfcm T\xfcrkiye’de",description:"Teknolojinin t\xfcm imk\xe2nlarını kullanarak, coğrafi sınırları ortadan kaldıran, interaktif ve y\xfcksek verimli online eğitim modellerimizle yanınızdayız."}],closingParagraph:"Başarıyı zirveye taşıyan eğitim yolculuğunda sağlam bir temel atmak, eksikleri hızla kapatmak, g\xfcvenli ve emin adımlarla hedefinize ulaşmak i\xe7in doğru adrestesiniz. Başarıya giden bu yolda AYBARİst AKADEMİ ailesi olarak her an yanınızda olmaktan gurur duyuyoruz."},r={eyebrow:"AYBARİst AKADEMİ’DE \xd6ZEL DERS",headline:"Sizin İ\xe7in Hazırladığımız Başarı Odaklı Eğitim Programlarımız",lead:"AYBARİst AKADEMİ'de geleceğinizi şansa bırakmayın; eğitimi uzmanından, bizzat size \xf6zel tasarlanmış bir programla alın. Alanında profesyonel, vizyoner kadromuzla ilkokuldan \xfcniversiteye, ulusal sınavlardan uluslararası kariyer basamaklarına kadar her yaş grubuna ve her seviyeye uygun, tamamen birebir \xf6zel derslerimizle başarıyı bir hedef olmaktan \xe7ıkarıp sizi zirveye taşıyan bir standart haline getiriyoruz.",closing:"Hedefiniz ne olursa olsun, birebir \xf6ğrenme modeli ve uzman kadromuzla başarıya giden en kısa ve etkili yolu birlikte inşa ediyoruz."},n=[{id:"sinav-hazirlik",code:"01",shortTitle:"Sınav Hazırlık",title:"Sınav Hazırlık \xd6ğrencileri",tagline:"Hayallerinizdeki \xdcniversite ve Liseler İ\xe7in Zirveye Yolculuk.",summary:"Sınav maratonunda kitlesel eğitimlerin kalabalığında kaybolmayın. Kişiye \xf6zel stratejilerle, eksiklerinizi avantaja d\xf6n\xfcşt\xfcr\xfcyoruz.",items:[{title:"YKS (TYT - AYT)",subjects:["Matematik","Geometri","Fizik","Kimya","Biyoloji","T\xfcrk Dili ve Edebiyatı","Tarih","Coğrafya","Felsefe","Psikoloji","Sosyoloji","Mantık","YKS KO\xc7LUK"]},{title:"LGS",subjects:["Matematik","Fen Bilgisi","T\xfcrk\xe7e","Sosyal Bilgiler","İngilizce","LGS KO\xc7LUK"]},{title:"KPSS (Genel Yetenek - Genel K\xfclt\xfcr)",subjects:["T\xfcrk\xe7e","Matematik","Tarih","Coğrafya","Vatandaşlık"]},{title:"KPSS Eğitim Bilimleri (\xd6ğretmen Adayları İ\xe7in)",featured:!0,leaderNote:"AYBARİst AKADEMİ Kurucusu Bahadır Aybar Liderliğinde T\xfcm Eğitim Bilimleri Birebir \xd6zel Dersleri.",description:"T\xfcm Eğitim Bilimleri dersleri bizzat kurumumuzun kurucusu Bahadır Aybar tarafından y\xfcksek akademik standartlarda verilmektedir.",subjects:["Eğitim Psikolojisi","Eğitimde \xd6ğretim Y\xf6ntem ve Teknikleri","\xd6l\xe7me ve Değerlendirme","Program Geliştirme","Rehberlik ve \xd6zel Eğitim","Sınıf Y\xf6netimi"]},{title:"ALES",subjects:["T\xfcrk\xe7e","S\xf6zel Mantık","Matematik","Geometri","Sayısal Mantık"]}]},{id:"okula-takviye",code:"02",shortTitle:"Okula Takviye",title:"Okula Takviye Programları",tagline:"Okul Sıralarında Tam \xd6ğrenme ve Kusursuz Başarı.",summary:"Her sınıf d\xfczeyinde yeni nesil Maarif Modeline tam uyumlu, kalıcı \xf6ğrenmeyi sağlayan KO\xc7LUK desteği.",items:[{title:"İlkokul D\xfczeyi (1 - 4. Sınıflar)",subjects:["T\xfcrk\xe7e","Matematik","Hayat Bilgisi ve Sosyal Bilgiler","Fen Bilgisi","İngilizce"]},{title:"Ortaokul D\xfczeyi (5 - 8. Sınıflar)",subjects:["T\xfcrk\xe7e","Matematik","Fen Bilgisi","T.C. İnkıl\xe2p Tarihi ve Atat\xfcrk\xe7\xfcl\xfck","Sosyal Bilgiler","İngilizce"]},{title:"Lise D\xfczeyi (9 - 12. Sınıflar)",subjects:["T\xfcrk Dili ve Edebiyatı","Matematik ve Geometri","Fizik","Kimya","Biyoloji","Tarih","Coğrafya","Felsefe","Psikoloji","Sosyoloji","Mantık"]}]},{id:"universite-akademik",code:"03",shortTitle:"\xdcniversite ve Akademik",title:"\xdcniversite D\xfczeyi ve Akademik Dersler",items:[{title:"AYBARİst AKADEMİ Kurucusu Bahadır Aybar'ın Liderliğinde İleri D\xfczey Akademik Mentorluk ve Birebir \xd6zel Dersler",featured:!0,description:"Felsefe, Sosyoloji ve Psikoloji b\xf6l\xfcmlerinde \xf6ğrenim g\xf6ren \xfcniversite \xf6ğrencilerine y\xf6nelik t\xfcm akademik dersler bizzat kurumumuzun kurucusu tarafından y\xfcksek akademik standartlarda verilmektedir.",subjects:["Felsefe","Sosyoloji","Psikoloji"]}]},{id:"dunya-dilleri",code:"04",shortTitle:"D\xfcnya Dilleri",title:"D\xfcnya Dilleri ve Uluslararası Sertifikasyon",tagline:"D\xfcnya ile Konuşun, Sınırları Kaldırın!",summary:"Yabancı dil eğitiminde sadece konuşmayı değil, kariyerinizi şekillendirecek k\xfcresel sınavları hedefliyoruz.",items:[{title:"İngilizce",subjects:["IELTS","TOEFL iBT","Cambridge English Exams (CPE, CAE, FCE)"]},{title:"Almanca",subjects:["Goethe-Zertifikat","TestDaF","telc Deutsch"]},{title:"Fransızca",subjects:["DELF","DALF","TCF / TEF"]},{title:"Rus\xe7a",subjects:["TORFL / TRKI"]},{title:"İtalyanca",subjects:["CELI","CILS","TOLC"]},{title:"İspanyolca",subjects:["DELE","SIELE"]},{title:"Arap\xe7a",subjects:["ALPT (Arabic Language Proficiency Test)"]},{title:"Felemenk\xe7e",subjects:["CNaVT","Staatsexamen NT2"]},{title:"\xc7ince",subjects:["HSK","HSKK (Speaking Test)"]},{title:"Japonca",subjects:["JLPT"]},{title:"Portekizce",subjects:["CAPLE","Celpe-Bras"]}]},{id:"ulusal-dil-sinavlari",code:"05",shortTitle:"YDT ve YDS",title:"T\xfcrkiye \xd6zelindeki Ulusal Yabancı Dil Sınavları",items:[{title:"YDT",subjects:["İngilizce","Almanca","Fransızca","Rus\xe7a","Arap\xe7a"]},{title:"YDS",subjects:["İngilizce","Almanca","Fransızca","Arap\xe7a","Rus\xe7a","İspanyolca","İtalyanca","\xc7ince","Hollandaca","Japonca","Portekizce"]}]},{id:"yasam-beceri-sanat",code:"06",shortTitle:"Yaşam, Beceri ve Sanat",title:"Yaşam, Beceri ve Sanat Odaklı Eğitimler",tagline:"Zihinsel Gelişimi Bedensel ve Sanatsal \xd6zg\xfcrl\xfckle Ta\xe7landırın.",summary:"Sadece akademik değil, hayatın her alanında donanımlı bireyler yetiştiriyoruz.",items:[{title:"Spor \xd6zel Dersleri",description:"Birebir eğitmen eşliğinde Y\xfczme dersleri",subjects:[]},{title:"S\xfcr\xfcc\xfcl\xfck Eğitimi",description:"G\xfcvenli ve profesyonel Direksiyon Dersleri",subjects:[]},{title:"Sanat Akademisi",description:"Ruhunuzu besleyen Dans ve M\xfczik eğitimleri",subjects:[]}]}],t={eyebrow:"EĞİTİM MODELİMİZ",headline:"Eğitim Modelimiz",lead:"AYBARİst AKADEMİ Eğitim Modeli; ezberci kalıpları yıkan, kişiye \xf6zel kurgulanmış VIP S\xfcre\xe7 Y\xf6netimi ve alanında uzman eğitmen kadrosuyla \xf6ğrencileri potansiyellerinin zirvesine taşıyan, Maarif Modeline uyumlu, b\xfct\xfcnc\xfcl bir rehberlik ve başarı platformudur.",sections:[{code:"01",shortTitle:"VIP S\xfcre\xe7 Y\xf6netimi",title:"VIP S\xfcre\xe7 Y\xf6netimi: Kişiye \xd6zel Eğitim Felsefesi",intro:"Standart ve kalabalık sınıfların sunduğu tek tip eğitim anlayışını geride bırakıyoruz. AYBARİst AKADEMİ'de eğitim; tamamen \xf6ğrencinin bireysel hızına, \xf6ğrenme stiline ve hedeflerine g\xf6re şekillenir:",points:[{label:"Birebir \xd6zel Dersler ve Esnek Format",text:"Dersler; \xf6ğrencinin tercihine g\xf6re ister y\xfcz y\xfcze ister online olarak, en verimli şekilde işlenir."},{label:"Deneyimli ve Profesyonel Kadro",text:"Alanında kanıtlanmış tecr\xfcbeye sahip, Yeni nesil Maarif Modeline h\xe2kim \xf6ğretmen kadromuz, sadece ders anlatmakla kalmaz; \xf6ğrenciye alanına ilişkin liderlik eder."},{label:"G\xfc\xe7l\xfc \xd6dev ve S\xfcre\xe7 Takibi",text:"Verilen her sorumluluk adım adım takip edilir, aksayan y\xf6nler anında fark edilerek telafi edilir."}]},{code:"02",shortTitle:"Eğitim Ko\xe7luğu",title:"Yol Arkadaşı Olarak Eğitim Ko\xe7luğu",intro:"Eğitim ko\xe7luğu; dışarıdan bir baskı aracı değil, \xf6ğrencinin kendi i\xe7indeki g\xfcc\xfc keşfetmesini sağlayan profesyonel bir yol arkadaşlığıdır.",points:[{label:"Zaman Y\xf6netimi ve Planlama \xb7 Ders Programı Hazırlama",text:"Okul, kurs, iş, sosyal ve kişisel zamanı dengeleyen, kişiye \xf6zel ve s\xfcrd\xfcr\xfclebilir \xe7alışma programları kurulur."},{label:"Erteleme ile M\xfccadele",text:"\xd6ğrencinin zamanı doğru y\xf6netmesi ve sorumluluklarını vaktinde yerine getirmesi denetlenir."},{label:"Etkili \xc7alışma Teknikleri",text:"\xd6ğrenciye hızlı okuma, kalıcı not alma, hafıza teknikleri ve zihin haritaları gibi bilimsel ve pratik \xf6ğrenme metotları kazandırılır."},{label:"Sınav Kaygısı ve Stres Y\xf6netimi",text:"\xd6zellikle LGS, YKS, KPSS ve ALES gibi d\xf6n\xfcm noktası niteliğindeki kritik sınav maratonlarında; yoğun stres, sınav kaygısı ve \xf6zg\xfcven eksikliği gibi duygusal engeller profesyonel yaklaşımlarla aşılır."}]},{code:"03",shortTitle:"Modelin Temel Taşları",title:"AYBARİst AKADEMİ Eğitim Modelinin Temel Taşları",intro:"",points:[{label:"Hedef Belirleme ve Strateji Geliştirme",text:"\xd6ğrencinin kısa ve uzun vadeli akademik (hayalindeki lise veya \xfcniversite) ve kişisel hedefleri netleştirilir; bu hedefe y\xfcr\xfcmek i\xe7in ger\xe7ek\xe7i eylem planları hazırlanır."},{label:"\xd6ğrenme Stratejileri ve Birebir Verimlilik",text:"Her \xf6ğrencinin g\xf6rsel, işitsel ya da kinestetik \xf6ğrenme modeline sahip olduğu ger\xe7eğinden hareketle; kitlesel eğitime veda edilir, tamamen birebir \xe7alışma modeli uygulanır."},{label:"İ\xe7sel Motivasyon",text:"\xd6ğrencinin ders \xe7alışmayı bir zorunluluk olmaktan \xe7ıkarıp kendi hedefleri doğrultusunda i\xe7sel bir istekle (baskı olmadan) harekete ge\xe7mesi sağlanır."},{label:"Performans Takibi ve Geri Bildirim",text:"Deneme ve yazılı sınav sonu\xe7ları, d\xfczenli olarak analiz edilir; programdaki aksaklıklar anında g\xfcncellenerek \xf6ğrenciye şeffaf geri bildirimler verilir."}]},{code:"04",shortTitle:"Aile, Veli ve Okul K\xf6pr\xfcs\xfc",title:"Aile, Veli ve Okul Arasında G\xfc\xe7l\xfc Bir K\xf6pr\xfc",intro:"Başarı yalnızca \xf6ğrenciyle sınırlı değildir. AYBARİst AKADEMİ'de her \xf6ğretmen; aile, veli ve okul \xfc\xe7geninde sağlıklı bir k\xf6pr\xfc g\xf6revi \xfcstlenir.",points:[{label:"",text:"Aileler, \xe7ocuklarının akademik gelişimi hakkında net ve şeffaf şekilde bilgilendirilir."},{label:"",text:"\xd6ğrenciye evde veya okulda yıpratıcı bir baskı kurulmasının \xf6n\xfcne ge\xe7ilerek pedagojik ve objektif y\xf6nlendirmelerle aileye rehberlik edilir."}]}]},s={eyebrow:"AYBARİst AKADEMİ NEDEN FARKLI?",headline:"AYBARİst AKADEMİ'de Fark Yaratan Standart İlkeler",lead:"AYBARİst AKADEMİ; \xf6zel derste sıradan bilgi aktarımını değil, bilimsel temelli bir s\xfcre\xe7 y\xf6netimini, kişiye \xf6zel m\xfchendislik yaklaşımını ve b\xfct\xfcnc\xfcl rehberliği standart hale getirir. Eğitim camiasında fark yaratan bu yaklaşım, “Tam \xd6ğrenme” modelini merkezine alarak \xf6ğrencileri sıfır hata ile zirveye taşır.",principlesHeading:"AYBARİst AKADEMİ'de Fark Yaratan Standart İlkeler",principles:[{step:"01",title:"Ders \xd6ncesi ve İlk Tanışma (Profesyonel Başlangı\xe7)",items:[{title:"\xd6ğrenme Stili Analizi",detail:"Bu s\xfcre\xe7te \xf6ğrencinin akademik altyapısı, g\xf6rsel/işitsel/kinestetik \xf6ğrenme stili ve derse karşı geliştirdiği zihinsel \xf6nyargılar saptanır."},{title:"\xd6ğrenci S\xf6zleşmesi",detail:"Karşılıklı sorumlulukları, ders saatine sadakati ve \xf6dev disiplinini netleştiren resmi olmayan bir “İş Birliği Taahh\xfcd\xfc” imzalanır. Sonrasında normal ders s\xfcresince ders yapılır."}]},{step:"02",title:"Derste Uygulanan Yenilik\xe7i Y\xf6ntemler",items:[{title:"Kişiselleştirilmiş Yol Haritası (Dashboard)",detail:"\xd6ğrenciye \xf6zel dijital veya basılı gelişim haritaları hazırlanır. Hangi konuda eksiklik olduğu, hangi konunun ne zaman biteceği g\xf6rselleştirilerek \xf6ğrencide “s\xfcre\xe7 kontrol\xfc” hissi uyandırılır."},{title:"Flipped Classroom (Ters Y\xfcz Sınıf) Modeli",detail:"Dersten bir g\xfcn \xf6nce \xf6ğrenciye 5-10 dakikalık kısa video, makale, soru veya form\xfcl g\xf6nderilir. B\xf6ylece \xf6ğrenci derse pasif bir dinleyici olarak başlamaz; aktif bir dinleyici ve katılımcı olarak, \xf6n bilgi oluşturmuş, soru \xe7\xf6zen, mantık y\xfcr\xfcten aktif bir birey olarak gelir."},{title:"Aktif Geri \xc7ağırma (Active Recall) Kartları",detail:"Her dersin son 10 dakikasında \xf6ğrenilenler flashcard'lara (bilgi kartlarına) d\xf6k\xfcl\xfcr. Bir sonraki dersin ilk 10 dakikasında bu kartlarla mini bilgi yarışması yapılır."}]},{step:"03",title:"Teknoloji ve Materyal Kullanımı",items:[{title:"Kişiye \xd6zel Hata Defteri ve Sıfırlama Tekniği",detail:"\xd6ğrencinin \xf6devlerde, denemelerde ya da yazılı sınavlarda takıldığı soru tipleri dijital bir hata defterine işlenir. Sınav \xf6ncesinde genel tekrar yerine yalnızca bu hata havuzu eritilir; hatalar sıfırlanır ve bu da net artışını katlar."}]},{step:"04",title:"Veli İlişkileri ve İletişim",items:[{title:"Profesyonel Ders Sonu Raporu",detail:"Her dersin bitiminde veliye WhatsApp \xfczerinden “Bug\xfcn ne işledik, \xf6ğrencinin durumu ne, \xf6dev nedir?” gibi başlıklar i\xe7eren net bir bilgilendirme bir şablon aracılığıyla iletilir."},{title:"Aylık Performans Değerlendirmesi",detail:"Aylık periyotlarla veliye; daha \xf6nce \xe7\xf6z\xfclemeyen ve artık \xe7\xf6z\xfclebilen yeni soru adetleri, deneme ve yazılı sınavlarındaki puan y\xfckselişleri ile odaklanma s\xfcresindeki gelişimi g\xf6steren k\xfc\xe7\xfck bir rapor sunulur."}]},{step:"05",title:"Mentorluk ve Psikolojik Destek",items:[{title:"Sadece \xd6ğretmen Değil, Aynı Zamanda Mentor",detail:"AYBARİst AKADEMİ \xf6ğretmenleri yalnızca ders anlatıp gitmez. Sınav stresi y\xf6netimi, zaman planlaması ve motivasyon konusunda mentorluk yapar. Ders i\xe7erisinde ya da ders dışı bir zamanda, birka\xe7 dakikasını \xf6ğrencisinin modunu y\xfckseltmeye, haftasının nasıl ge\xe7tiğini dinlemeye ayırır. Sınav kaygısı y\xf6netimi, zaman y\xf6netimi ve verimli ders \xe7alışma teknikleri konusunda da rehberlik yapar."},{title:"Kesintisiz Ulaşılabilirlik (Soru Hattı)",detail:"\xd6ğrenci evde \xe7alışırken takıldığı sorunun fotoğrafını atar ya da bir bilgiyi sorar; \xf6ğretmen m\xfcsait olduğu ilk anda ses kaydı, yazılı soru \xe7\xf6z\xfcm\xfc veya video \xe7\xf6z\xfcmle destek olur."}]}],pedagogicalOutcome:{title:"Pedagojik Sonu\xe7: Tam \xd6ğrenme ve Zirveye Ulaşım",body:"Bu 5 temel ilke; \xf6ğretimi bir “ezber aktarımı” olmaktan \xe7ıkarıp \xf6l\xe7\xfclebilir, denetlenebilir ve psikolojik olarak desteklenen bir sisteme d\xf6n\xfcşt\xfcr\xfcr. Flipped classroom ile \xf6n \xf6ğrenme sağlanır, Active recall ile kalıcı hafıza pekiştirilir, dijital hata defteriyle eksikler sıfırlanır ve veli-\xf6ğrenci-\xf6ğretmen \xfc\xe7geni şeffaf bir g\xfcven ilişkisiyle y\xfcr\xfct\xfcl\xfcr. Sonu\xe7ta \xf6ğrenci, sınav kaygısından arınmış, kendi \xf6ğrenme stilinin farkında ve “Tam \xd6ğrenme” d\xfczeyine erişmiş olarak başarıya ulaşır."}}}}]);